{"file_path":"src/policies.js","content":"/**
 * The two limiter policies. Each keeps one independent state per key, and each
 * answers the same three questions: advance a key's state to a tick, tell
 * whether that key may pass, and record that it did.
 *
 * Every quantity is a BigInt so that ticks and counts of any size behave, and
 * so that a bucket's partial refills stay exact.
 */

/**
 * A token bucket. A key's state starts full at the tick it first arrives, and
 * every `per` ticks adds `refill` tokens up to `capacity`. Tokens are held as
 * a numerator over the fixed denominator `per`, which makes the accumulation
 * of partial periods exact: after n ticks the bucket has gained exactly
 * refill * n / per tokens, with nothing rounded away.
 */
export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.ceiling = capacity * per
    this.states = new Map()
  }

  stateFor(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { tokens: this.ceiling, at: tick }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.stateFor(key, tick)
    const elapsed = tick - state.at
    if (elapsed > 0n) {
      state.tokens += this.refill * elapsed
      if (state.tokens > this.ceiling) state.tokens = this.ceiling
      state.at = tick
    }
  }

  allows(key, tick) {
    return this.stateFor(key, tick).tokens >= this.per
  }

  record(key, tick) {
    const state = this.stateFor(key, tick)
    state.tokens -= this.per
  }
}

/**
 * A sliding window. A key's state remembers the ticks of the requests it
 * recorded; advancing to a tick forgets everything at or before tick - span,
 * so the window covers the `span` ticks ending at the current one. Remembered
 * ticks only ever grow, so the forgotten ones are dropped from the front.
 */
export class SlidingWindow {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  stateFor(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [], head: 0 }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.stateFor(key)
    const cutoff = tick - this.span
    while (state.head < state.ticks.length && state.ticks[state.head] <= cutoff) state.head += 1
    if (state.head > 0 && state.head === state.ticks.length) {
      state.ticks = []
      state.head = 0
    }
  }

  allows(key) {
    const state = this.stateFor(key)
    return BigInt(state.ticks.length - state.head) < this.limit
  }

  record(key, tick) {
    this.stateFor(key).ticks.push(tick)
  }
}
"}

