{"file_path":"src/parse.js","content":"/**
 * The limiter file reader. It turns the text of a file into the declarations,
 * the routes and the event log it describes, and refuses anything the
 * specification does not allow with the first reason it finds.
 *
 * Every line is checked left to right: first that its words have the shape the
 * directive wants, then that the names it uses do not clash with or miss the
 * declarations around them, and last that a declaration is not standing after
 * the log has begun.
 */

import { lineError } from './errors.js'

const NAME = /^[A-Za-z0-9_./:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

const SHAPES = {
  bucket: 'expected bucket <name> <capacity> <refill> <per>',
  window: 'expected window <name> <limit> <span>',
  route: 'expected route <prefix> <policy>...',
  event: 'expected event <tick> <key>',
}

/** Tells whether a word is a name, a route prefix or an event key. */
function isName(word) {
  return NAME.test(word)
}

/**
 * Reads a count field: an unsigned decimal integer without a leading zero,
 * that is at least `least`.
 */
function readCount(word, field, least, lineNumber) {
  if (!COUNT.test(word)) {
    throw lineError(lineNumber, `${field} must be an integer of at least ${least}`)
  }
  const value = BigInt(word)
  if (value < BigInt(least)) {
    throw lineError(lineNumber, `${field} must be an integer of at least ${least}`)
  }
  return value
}

/**
 * Splits the input into its lines, dropping the empty tail that a trailing
 * newline leaves behind.
 */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parses a whole limiter file. The result holds the declared policies in
 * declaration order, the routes in the order written, and the events in log
 * order. Nothing is simulated here, so a file that fails to parse has produced
 * no output at all.
 */
export function parseFile(text) {
  const declarations = []
  const names = new Set()
  const routes = []
  const prefixes = new Set()
  const events = []
  let lastTick = null

  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const lineNumber = index + 1
    const line = lines[index].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'bucket' || directive === 'window') {
      const isBucket = directive === 'bucket'
      if (words.length !== (isBucket ? 5 : 4)) {
        throw lineError(lineNumber, SHAPES[directive])
      }
      const name = words[1]
      if (!isName(name)) throw lineError(lineNumber, `invalid policy name ${name}`)
      const counts = isBucket
        ? [
            readCount(words[2], 'capacity', 1, lineNumber),
            readCount(words[3], 'refill', 0, lineNumber),
            readCount(words[4], 'per', 1, lineNumber),
          ]
        : [
            readCount(words[2], 'limit', 0, lineNumber),
            readCount(words[3], 'span', 1, lineNumber),
          ]
      if (names.has(name)) throw lineError(lineNumber, `policy ${name} is declared twice`)
      if (events.length > 0) {
        throw lineError(lineNumber, 'declarations must come before the first event')
      }
      names.add(name)
      declarations.push({ kind: directive, name, counts })
      continue
    }

    if (directive === 'route') {
      if (words.length < 3) throw lineError(lineNumber, SHAPES.route)
      const prefix = words[1]
      if (!isName(prefix)) throw lineError(lineNumber, `invalid route prefix ${prefix}`)
      const policies = words.slice(2)
      for (const policy of policies) {
        if (!isName(policy)) throw lineError(lineNumber, `invalid policy name ${policy}`)
      }
      if (prefixes.has(prefix)) throw lineError(lineNumber, `prefix ${prefix} is routed twice`)
      for (const policy of policies) {
        if (!names.has(policy)) throw lineError(lineNumber, `unknown policy ${policy}`)
      }
      if (events.length > 0) {
        throw lineError(lineNumber, 'declarations must come before the first event')
      }
      prefixes.add(prefix)
      routes.push({ prefix, policies })
      continue
    }

    if (directive === 'event') {
      if (words.length !== 3) throw lineError(lineNumber, SHAPES.event)
      const tickWord = words[1]
      const tick = readCount(tickWord, 'tick', 0, lineNumber)
      const key = words[2]
      if (!isName(key)) throw lineError(lineNumber, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw lineError(lineNumber, `tick ${tickWord} is before tick ${lastTick}`)
      }
      lastTick = tick
      events.push({ tick, tickText: tickWord, key })
      continue
    }

    throw lineError(lineNumber, `unknown directive ${directive}`)
  }

  return { declarations, routes, events }
}
"}

