{"file_path":"src/simulate.js","content":"/**
 * The simulation. Every event is sent to the route whose prefix it starts with
 * and which is the longest of those that match; a key no route matches is
 * always allowed. The policies of that route all advance to the event's tick,
 * then all of them are asked, and only when every one allows it does every one
 * record it, so a denied event leaves each stored allowance untouched.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

function buildPolicies(declarations) {
  const policies = new Map()
  for (const declaration of declarations) {
    const { kind, name, counts } = declaration
    policies.set(
      name,
      kind === 'bucket'
        ? new TokenBucket(name, counts[0], counts[1], counts[2])
        : new SlidingWindow(name, counts[0], counts[1]),
    )
  }
  return policies
}

/** Finds the longest route prefix the key starts with, if there is one. */
function routeFor(routes, key) {
  let best = null
  for (const route of routes) {
    if (!key.startsWith(route.prefix)) continue
    if (best === null || route.prefix.length > best.prefix.length) best = route
  }
  return best
}

/**
 * Replays the log and reports one verdict per event, in log order: either
 * `{ allowed: true }` or the name of the first policy on the route, in the
 * order the route wrote them, that refused.
 */
export function simulate(program) {
  const policies = buildPolicies(program.declarations)
  const verdicts = []

  for (const event of program.events) {
    const route = routeFor(program.routes, event.key)
    const chain = route === null ? [] : route.policies.map((name) => policies.get(name))

    for (const policy of chain) policy.advance(event.key, event.tick)

    let refused = null
    for (const policy of chain) {
      if (!policy.allows(event.key, event.tick)) {
        refused = policy.name
        break
      }
    }

    if (refused === null) {
      for (const policy of chain) policy.record(event.key, event.tick)
    }
    verdicts.push({ event, refused })
  }

  return verdicts
}

/** Formats the verdicts as `replay` prints them. */
export function replayReport(verdicts) {
  const lines = []
  for (const { event, refused } of verdicts) {
    const verdict = refused === null ? 'allow' : `deny ${refused}`
    lines.push(`${event.tickText} ${event.key} ${verdict}\n`)
  }
  return lines.join('')
}

/** Formats the verdicts as `summary` prints them. */
export function summaryReport(verdicts) {
  const perKey = new Map()
  let allowed = 0
  let denied = 0

  for (const { event, refused } of verdicts) {
    let counts = perKey.get(event.key)
    if (counts === undefined) {
      counts = { allowed: 0, denied: 0 }
      perKey.set(event.key, counts)
    }
    if (refused === null) {
      counts.allowed += 1
      allowed += 1
    } else {
      counts.denied += 1
      denied += 1
    }
  }

  const keys = [...perKey.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  const lines = keys.map((key) => {
    const counts = perKey.get(key)
    return `${key} allowed=${counts.allowed} denied=${counts.denied}\n`
  })
  lines.push(`total allowed=${allowed} denied=${denied}\n`)
  return lines.join('')
}
