import { CliError, usageError } from './errors.js'
import { parseFile } from './parse.js'
import { simulate, replayReport, summaryReport } from './simulate.js'

const MODES = new Set(['replay', 'summary'])

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
